"""Interaction functions for the Treatment Field Definition window UI in the Mosaiq application.
This window is displayed by selecting the Tx Field button from the D and I window"""

from .objects.mosaiq_d_and_i_objects import DandI
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions import CommonActions


def __find_tx_field_window() -> bool:
    """Searches for the Treatment Fields window within the D and I workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.treatment_Field_Main_Window) is not None else False


def __find_xvi_presets_dialog() -> bool:
    """Searches for the XVI Presets dialog window within the D and I workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DandI.xvi_Preset_List_Window) is not None else False


def __expand_treatment_Tolerance_dropdown() -> None:
    """Clicks the dropdown expander button of the Tolerance field in the Tx Field UI

    :raises Exception: This is raised if the Tolerance dropdown item is not found
    """
    if CommonActions.find_object(DandI.treatment_Tolerance) is None:
        raise Exception(f"Tolerance dropdown not found")
    CommonActions.left_click_object(DandI.treatment_Tolerance)


