@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def enter_text_in_treatment_Field(treatmentText: str) -> None:
    """Enters given treatmentText string into the Treatment Field textbox of the Tx Field UI.

    :param str treatmentText: Text to enter in treatment_Field
    """
    if CommonActions.find_object(DandI.treatment_Field_Textbox) is None:
        raise Exception(f"Treatment Field text box not found")
