@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_option_for_Tolerance(toleranceOption: str) -> None:
    """Expands the Tolerance dropdown and selects a given toleranceOption from the dropdown menu

    :param str toleranceOption: Tolerance option to select from dropdown
    """
    __expand_treatment_Tolerance_dropdown()
    toleranceObject = CommonActions.get_object_by_ocr_text_in_object(DandI.treatment_Tolerance_Options, toleranceOption)
    if toleranceObject is not None:
        CommonActions.click_screen_area_object(toleranceObject)
    else:
        # If tolerance string is "TT4" to "TT8", try selecting tolerance by keyboard shortcut
        tolerance_tt_list = ["TT4", "TT5", "TT6", "TT7", "TT8"]
        if toleranceOption in tolerance_tt_list:
            list_index = tolerance_tt_list.index(toleranceOption) + 1
            for i in range(list_index):
                CommonActions.press_key_sequence("T")


