@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_tx_fields_OK_button(txFieldWindowTimeout: int = 10) -> None:
    """Clicks the OK button of the main Tx Fields UI.
    :param int txFieldWindowTimeout: Time in seconds to wait for the Tx Field window to disappear after clicking OK
    """
    if CommonActions.find_object(DandI.treatment_oK_Button) is None:
        raise Exception(f"Ok button not found on main window")
    CommonActions.left_click_object(DandI.treatment_oK_Button)
    CommonActions.wait_for_object_to_disappear(DandI.treatment_Field_Main_Window, timeoutInSecs=txFieldWindowTimeout)